    "code": "const show = value => { const out = document.querySelector(\"#output\"); if (out) out.textContent = typeof value === \"string\" ? value : JSON.stringify(value, null, 2); };\ndocument.querySelector(\"#action\").addEventListener(\"click\",()=>{document.querySelectorAll(\".item\").forEach(item=>item.hidden=item.dataset.category!==\"web\");show(\"ჩანს მხოლოდ ვების კატეგორია.\");});",
